// Command crdtrim removes CRD versions that controller-gen generated by mistake.
//
// controller-gen builds a CRD version for every API package in a group that
// declares a type named like the kind, root object or not. v1alpha1 has a
// Workflow status struct named Task, so tasks.tinkerbell.org (a v1alpha2-only
// kind) gets a bogus v1alpha1 version. There is no per-type marker to suppress
// that, so this runs after controller-gen.
//
// Usage: crdtrim <file>:<version> [<file>:<version> ...]
package main

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"sigs.k8s.io/yaml"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: crdtrim <file>:<version> ...")
		os.Exit(2)
	}
	for _, arg := range os.Args[1:] {
		file, version, ok := strings.Cut(arg, ":")
		if !ok {
			fmt.Fprintf(os.Stderr, "invalid argument %q: want <file>:<version>\n", arg)
			os.Exit(2)
		}
		if err := trim(file, version); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
}

func trim(file, version string) error {
	raw, err := os.ReadFile(file) //nolint:gosec // a build tool run by go generate on paths in this repository
	if err != nil {
		return err
	}
	var crd map[string]any
	if err := yaml.Unmarshal(raw, &crd); err != nil {
		return fmt.Errorf("%s: %w", file, err)
	}
	spec, _ := crd["spec"].(map[string]any)
	versions, _ := spec["versions"].([]any)
	kept := make([]any, 0, len(versions))
	for _, v := range versions {
		if m, _ := v.(map[string]any); m["name"] == version {
			continue
		}
		kept = append(kept, v)
	}
	if len(kept) == len(versions) {
		return nil
	}
	if len(kept) == 0 {
		return fmt.Errorf("%s: refusing to remove the only version %q", file, version)
	}
	spec["versions"] = kept
	out, err := yaml.Marshal(crd)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	buf.WriteString("---\n")
	buf.Write(out)
	return os.WriteFile(file, buf.Bytes(), 0o644) //nolint:gosec // generated, world-readable source file
}
